  let mut result=json!({"vendor":"paloalto-panos","parser_version":"panos-config-v1","hostname":hostname,"context":"vsys1","artifact_sha256":hash,"source_lines":source,"evidence":evidence,"chains":chains,"warnings":warnings,"capabilities":["PAN-OS SET format","IPv4 static and connected routes","ordered security policy","bounded static NAT"],"rule_origins":origins,"path":path});if result["rule_origins"].as_array().is_some_and(|x|x.is_empty()){result.as_object_mut().unwrap().remove("rule_origins");}Ok(result)
